args.content:
SELECT ?item ?itemLabel ?coordinates
WHERE {
  ?item wdt:P31/wdt:P279* wd:Q159052 ;
        wdt:P625 ?coordinates.
  OPTIONAL { ?item wdt:P131* wd:Q8813 . }
  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en" .
  }
}

